//! Cargo-driven `ftp.exe` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is ftp-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/base/applications/network/ftp",
        "base/applications/network/ftp",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &["WINVER=0x502", "_WIN32_WINNT=0x502", "lint"];

    let (target_json, entry) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_mainCRTStartup"),
        "x86_64" => ("x86_64-pc-windows-gnu", "mainCRTStartup"),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "mainCRTStartup"),
        o => panic!("ftp-cargo: unsupported arch {o}"),
    };

    let late_libs: &[&str] = match arch.as_str() {
        "x86" => &["engine:oldnames", "engine:pseh", "engine:chkstk"],
        "x86_64" => &["engine:oldnames", "engine:pseh"],
        "aarch64" => &["engine:oldnames", "engine:pseh", "engine:chkstk"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("ftp-rust")
        .c_from_compile_db("ftp_shims", &["base/applications/network/ftp/rust_varargs_shim.c"])
        .rc("base/applications/network/ftp/ftp.rc", rc_includes, rc_flags, rc_defines)
        .import_lib("dll/win32/ws2_32/ws2_32.spec", "ws2_32.dll", "ws2_32")
        .import_lib("dll/win32/iphlpapi/iphlpapi.spec", "iphlpapi.dll", "iphlpapi")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // ...and those cmake linked after the body, in the same order.
        .static_libs_after_body(late_libs)
        .msvcrtex_crt(MsvcrtexKind::ExeAnsi)
        .link(ModuleKind::Win32Exe {
            entry: entry.into(),
            subsystem: "console:5.01".into(),
        });
}
